/**
 * @method
 * @name scwin.selectBox
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.selectBox = function (ver) {
    /* sdd-asis-lifecycle:begin selectBox — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const date = new Date();
    let year;
    let month;
    date.setMonth(date.getMonth(), 1);
    document.write("<option value='000000'>--- 선택 ---</option>");
    for (let i = 1; i < 13; i++) {
        if (ver == 0) {
            year = date.getFullYear();
            month = (date.getMonth() + 1) + "";
            if (month.length == 1) {
                month = "0" + month;
            }
            date.setMonth(date.getMonth() + 1);
            document.write("<option value='" + (year + "" + month) + "'>" + year + "년" + month + "월" + "</option>");
        } else {
            document.write("<option value='" + i + "'>" + i + "월" + "</option>");
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
